#include <stdio.h>
#include <stdlib.h>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

// Helper function to perform inorder traversal
void inorder(struct TreeNode* root, int* arr, int* size) {
    if (root == NULL)
        return;

    inorder(root->left, arr, size);   // Traverse left subtree
    arr[(*size)++] = root->val;       // Visit node
    inorder(root->right, arr, size);  // Traverse right subtree
}

// LeetCode-style function signature
int* inorderTraversal(struct TreeNode* root, int* returnSize) {
    int* result = (int*)malloc(1000 * sizeof(int)); // assume max 1000 nodes
    *returnSize = 0;
    inorder(root, result, returnSize);
    return result;
}

// --- For your local testing ---
struct TreeNode* newNode(int val) {
    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    node->val = val;
    node->left = node->right = NULL;
    return node;
}

int main() {
    // Example Tree:
    //       1
    //        \
    //         2
    //        /
    //       3
    struct TreeNode* root = newNode(1);
    root->right = newNode(2);
    root->right->left = newNode(3);

    int size;
    int* res = inorderTraversal(root, &size);

    printf("Inorder Traversal: ");
    for (int i = 0; i < size; i++)
        printf("%d ", res[i]);
    printf("\n");

    free(res);
    return 0;
}
```

