/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode* prev = NULL;
    struct ListNode* curr = head;
    struct ListNode* next = NULL;

    while (curr != NULL) {
        next = curr->next;   // store next node
        curr->next = prev;   // reverse pointer
        prev = curr;         // move prev ahead
        curr = next;         // move curr ahead
    }

    return prev;  // new head after reversal
}
```

---

### 💬 How it works
- `prev` tracks the **reversed part** of the list.  
- `curr` walks through the list.  
- `next` is a temporary pointer so we don’t lose the rest of the list.  
- Each iteration flips the link direction (`curr->next = prev`).  

